        command += ['exec', '--sandbox', 'read-only' if args.access == 'read' else 'workspace-write',
                    '-c', 'approval_policy="never"', '--json',
                    '--output-last-message', str(run_dir / 'result.md')]
        if args.skip_git_check:
            command += ['--skip-git-repo-check']
