"""Incremental, best-effort display. Never used to decide job success."""
import json
import time
from pathlib import Path


def clean(value, limit=240):
    return ''.join(c if c.isprintable() else ' ' for c in str(value))[:limit]


def cursor_tool(call):
    """Name, key argument and outcome of a Cursor tool_call payload."""
    for key, value in call.items():
        if not isinstance(value, dict) or not (key.endswith('ToolCall') or key == 'function'):
            continue
        name = key[:-len('ToolCall')] if key.endswith('ToolCall') else value.get('name', key)
        args = value.get('args') or value.get('arguments') or {}
        if isinstance(args, dict):
            detail = next((args[k] for k in ('command', 'path', 'pattern', 'query', 'url', 'globPattern')
                           if args.get(k)), json.dumps(args, ensure_ascii=False))
        else:
            detail = args
        result = value.get('result')
        success = result.get('success') if isinstance(result, dict) else None
        exit_code = success.get('exitCode') if isinstance(success, dict) else None
        failed = isinstance(result, dict) and bool({'error', 'failure', 'rejected'} & set(result))
        if exit_code is not None:
            detail = str(detail) + ' [exit=' + str(exit_code) + ']'
        return clean(name, 60), clean(detail), not failed and exit_code in (None, 0)
    return 'tool', '', True


class Progress:
    def __init__(self, meta):
        self.meta = meta
        self.offsets = {}
        self.pending = {}
        self.last_activity = time.monotonic()
        self.last_notice = self.last_activity
        self.echo = False
        self.path = Path(meta['run_dir']) / 'progress.log'
        model = meta.get('model') or meta.get('requested_model') or '默认模型'
        if meta.get('thinking'):
            model += '/' + meta['thinking']
        mode = '只读' if meta.get('access') == 'read' else '可写'
        self.write('● ' + meta['agent'] + ' · ' + model + ' · ' + mode + ' | ' + meta['cwd'])

    def write(self, text):
        line = time.strftime('%H:%M:%S ') + clean(text, 1600)
        with self.path.open('a', encoding='utf-8') as out:
            out.write(line + '\n')
        if self.echo:
            print(line, flush=True)

    def echo_on(self):
        """Mirror progress to stdout, so a host's background-task view shows it live."""
        logged = self.path.read_text(encoding='utf-8').rstrip('\n') if self.path.exists() else ''
        if logged:
            print(logged, flush=True)
        self.echo = True

    def lines(self, path):
        if not path.exists():
            return []
        key = str(path)
        with path.open('rb') as stream:
            stream.seek(self.offsets.get(key, 0))
            data = stream.read()
            self.offsets[key] = stream.tell()
        if data:
            self.last_activity = time.monotonic()
        parts = (self.pending.get(key, b'') + data).split(b'\n')
        self.pending[key] = parts.pop()
        return [line.decode('utf-8', errors='replace') for line in parts]

    def poll(self):
        root = Path(self.meta['run_dir'])
        agent = self.meta['agent']
        if agent in ('codex', 'cursor'):
            paths = [root / 'events.jsonl']
        else:
            paths = ([Path(self.meta['session_file'])] if self.meta.get('session_file')
                     else list((root / 'sessions').rglob('*.jsonl')))
        for path in paths:
            for line in self.lines(path):
                try:
                    e = json.loads(line)
                    if not isinstance(e, dict):
                        continue
                    if agent == 'codex':
                        self.codex(e)
                    elif agent == 'cursor':
                        self.cursor(e)
                    else:
                        self.pi(e, path)
                except (ValueError, TypeError, KeyError, AttributeError):
                    continue
        for line in self.lines(root / 'stderr.log'):
            if line.strip():
                self.write('! ' + clean(line))
        now = time.monotonic()
        if now - self.last_activity >= 60 and now - self.last_notice >= 60:
            self.write('… 已 ' + str(int(now-self.last_activity)) + ' 秒无日志更新；不代表卡死')
            self.last_notice = now

    def session(self, value):
        if value and value != self.meta.get('session_id'):
            self.meta['session_id'] = value
            self.write('会话 ' + clean(value))

    def codex(self, e):
        kind = e.get('type')
        if kind == 'thread.started':
            self.session(e.get('thread_id'))
        elif kind in ('item.started', 'item.completed'):
            item = e.get('item') or {}
            t = item.get('type')
            done = kind == 'item.completed'
            if t == 'command_execution':
                label = ('✓' if item.get('exit_code') == 0 else '!') if done else '▶'
                self.write(label + ' ' + clean(item.get('command', '')) +
                           (' [exit=' + str(item.get('exit_code')) + ']' if done else ''))
            elif t == 'file_change' and done:
                self.write('✎ ' + ', '.join(clean(c.get('path', '')) for c in item.get('changes', [])))
            elif t == 'agent_message' and done:
                self.write('💬 ' + clean(item.get('text', ''), 1200))
            elif t == 'mcp_tool_call':
                self.write(('✓ ' if done else '▶ ') + 'MCP ' + clean(item.get('tool', '')))
        elif kind in ('turn.failed', 'error'):
            self.write('! ' + clean(e.get('error', e.get('message', kind))))
        elif kind == 'turn.completed':
            self.write('● 本轮完成；待主控验收')

    def cursor(self, e):
        kind = e.get('type')
        self.session(e.get('session_id'))
        if kind == 'system' and e.get('subtype') == 'init':
            self.write('模型 ' + clean(e.get('model', '')))
        elif kind == 'tool_call' and e.get('subtype') in ('started', 'completed'):
            name, detail, ok = cursor_tool(e.get('tool_call') or {})
            label = '▶' if e['subtype'] == 'started' else ('✓' if ok else '!')
            if name in ('edit', 'write', 'delete') and e['subtype'] == 'completed' and ok:
                label = '✎'
            self.write(label + ' ' + name + ' ' + detail)
        elif kind == 'assistant':
            parts = (e.get('message') or {}).get('content') or []
            text = ''.join(p.get('text', '') for p in parts if isinstance(p, dict) and p.get('type') == 'text')
            if text.strip():
                self.write('💬 ' + clean(text, 1200))
        elif kind == 'result':
            self.write('! 本轮出错' if e.get('is_error') else '● 本轮完成；待主控验收')

    def pi(self, e, path):
        if e.get('type') == 'session':
            self.meta['session_file'] = str(path.resolve())
            self.session(e.get('id'))
        m = e.get('message') or {}
        if m.get('role') == 'assistant':
            for part in m.get('content', []):
                if not isinstance(part, dict):
                    continue
                if part.get('type') == 'toolCall':
                    self.write('▶ ' + clean(part.get('name')) + ' ' + clean(part.get('arguments', {})))
                elif part.get('type') == 'text':
                    self.write('💬 ' + clean(part.get('text', ''), 1200))
        elif m.get('role') == 'toolResult':
            self.write(('! ' if m.get('isError') else '✓ ') + clean(m.get('toolName', 'tool')))

const RUN_DIR = /^(\d{4})(\d{2})(\d{2})-(\d{2})(\d{2})(\d{2})-(codex|pi|cursor)-/
const ACTIVE = new Set(['running', 'preparing'])
const STATUS: Record<string, string> = {
  running: '运行中',
  preparing: '准备中',
  process_succeeded: '完成·待验收',
  failed: '失败',
  blocked: '受阻',
  timed_out: '超时',
  cancelled: '已取消',
  planned: '仅计划',
}

// Change a tag when that value's fields change: it declines what an earlier
// version stored, which outlives a reload.
const runs = atom({ plugin: 'delegate-cli-panel', key: 'runs' } as const, [], { shape: 'runs-1' })
const detail = atom({ plugin: 'delegate-cli-panel', key: 'detail' } as const, null, { shape: 'detail-1' })
const selected = atom({ plugin: 'delegate-cli-panel', key: 'selected' } as const, null)
const scope = atom({ plugin: 'delegate-cli-panel', key: 'scope' } as const, 'mine')
const autoOpened = atom({ plugin: 'delegate-cli-panel', key: 'autoOpened' } as const, [])

// A finished run's files never change again, so it is read once per load.
const finished = new Map<string, RunRow>()
const tails = new Map<string, { size: number; mtimeMs: number; lines: string[] }>()
let isBusy = false
let lastScan = 0
let isWoken = false
let lastStatus: string | undefined
let isPaneHeld = false

const text = (value: unknown) => (typeof value === 'string' ? value : '')
const num = (value: unknown) => (typeof value === 'number' && Number.isFinite(value) ? value : null)

function stampOf(name: string) {
  const m = RUN_DIR.exec(name)
  if (!m) return 0
  const [y, mo, d, h, mi, s] = m.slice(1, 7).map(Number) as [number, number, number, number, number, number]

  return new Date(y, mo - 1, d, h, mi, s).getTime()
}

async function readTail($: EngineInterface, path: string, size: number, mtimeMs: number) {
