function duration(ms: number) {
  const s = Math.max(0, Math.round(ms / 1000))
  if (s < 60) return `${s}s`
  if (s < 3600) return `${Math.floor(s / 60)}m${String(s % 60).padStart(2, '0')}s`
  return `${Math.floor(s / 3600)}h${String(Math.floor((s % 3600) / 60)).padStart(2, '0')}m`
}

function tokens(n: number | null) {
  if (n === null) return ''
  const shown = n >= 1e6 ? `${(n / 1e6).toFixed(2)}M` : n >= 1e3 ? `${(n / 1e3).toFixed(1)}k` : String(n)
  return ` · ${shown} tok`
}

function badge(run: RunRow) {
  if (ACTIVE.has(run.status)) return run.isStale ? { glyph: '◌', tone: 'warning' } : { glyph: '●', tone: 'warning' }
  if (run.status === 'process_succeeded') return { glyph: '✓', tone: 'success' }
  if (run.status === 'planned') return { glyph: '○', tone: 'inactive' }
  return { glyph: '✗', tone: 'error' }
}

function summary(run: RunRow, now: number) {
  const status = run.isStale ? '可能已中断' : (STATUS[run.status] ?? run.status)
  return `${status} · ${duration((run.finishedAt ?? now) - run.startedAt)}${tokens(run.tokens)}`
}

// Newest lines that fit the pane, each cut to a few wrapped rows, oldest first.
function fit(lines: string[], columns: number, rows: number) {
  const shown: string[] = []
  let used = 0
  for (let i = lines.length - 1; i >= 0 && used < rows; i--) {
    const raw = lines[i] ?? ''
    const line = raw.length > columns * 4 ? `${raw.slice(0, columns * 4 - 1)}…` : raw
    let width = 0
    for (const ch of line) width += ch.charCodeAt(0) > 0x2e80 ? 2 : 1
    used += Math.max(1, Math.ceil(width / columns))
    shown.unshift(line)
  }
  return shown
}

